mapper.update:
update jiedan_quote set title=#{title},requirement=#{requirement},attachments=#{attachments},source_name=#{sourceName},source_seq=#{sourceSeq},
     last_sent_time=now(),
     notice_version=notice_version+1,employee_id=#{employeeId},amount=#{amount},quote_note=#{quoteNote},status=#{status},order_id=#{orderId},deleted=#{deleted},version=version+1,update_time=now() where id=#{id}

mapper.insert:
insert into jiedan_quote_read(quote_id,member_id,read_version) select q.id,#{memberId},q.notice_version from jiedan_quote q where q.deleted=0 and (q.id,q.notice_version) in (#{item.id},#{item.noticeVersion})
and q.employee_id=#{employeeId} and q.status='pending' and q.status='quoted' and q.creator_id=#{memberId}
order by q.id on duplicate key update read_version=greatest(jiedan_quote_read.read_version,values(read_version))

mapper.select:
select id,employee_id employeeId,author_id authorId,author_name authorName,recipient_id recipientId,kind,content,attachments,amount,
  date_format(created_at,'%Y-%m-%d %H:%i:%s') createdAt
from jiedan_quote_message where quote_id=#{quoteId}
and employee_id=#{employee}
and id < #{before}
order by id desc limit 41
